<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import {notify} from '../lib'
import Icon from './Icon.vue'
import RoundedSelect from './RoundedSelect.vue'
import MediaCategoryCondition from './MediaCategoryCondition.vue'
import {mediaCategoryTypes,mediaCategoryId,mediaCategoryLeaf} from '../media-category'
const props=defineProps({modelValue:{type:Object,required:true},fields:{type:Array,default:()=>[]},disabled:Boolean,error:String})
const emit=defineEmits(['update:modelValue'])
const tab=ref('directories'),mediaType=ref('tv')
const directories=computed(()=>props.modelValue.directories.filter(d=>d.mediaType===mediaType.value&&d.path.length>0))
const fallbackOptions=kind=>props.modelValue.directories.filter(d=>d.mediaType===kind&&d.enabled).map(d=>({value:d.id,label:d.path.length?`${d.name} · ${d.path.join('/')}`:`${d.name}根目录`}))
const ruleTargets=rule=>props.modelValue.directories.filter(d=>d.mediaType===rule.mediaType&&(d.enabled||d.id===rule.directoryId)).map(d=>({value:d.id,label:(d.path.length?`${d.name} · ${d.path.join('/')}`:`${d.name}根目录`)+(d.enabled?'':'（已停用）')}))
watch(()=>props.error,message=>{if(!message)return;if(message.includes('规则')||message.includes('条件'))tab.value='rules';else if(message.includes('目录'))tab.value='directories'})
function patch(value){emit('update:modelValue',{...props.modelValue,...value})}
function directory(id,value){patch({directories:props.modelValue.directories.map(d=>d.id===id?{...d,...value}:d)})}
function directoryUsed(id){return Object.values(props.modelValue.fallbacks).includes(id)||props.modelValue.rules.some(r=>r.directoryId===id)}
function disableUsed(id){return Object.values(props.modelValue.fallbacks).includes(id)||props.modelValue.rules.some(r=>r.enabled&&r.directoryId===id)}
function addDirectory(){patch({directories:[...props.modelValue.directories,{id:mediaCategoryId(),mediaType:mediaType.value,name:'',path:[''],enabled:true}]})}
function removeDirectory(id){if(directoryUsed(id)){notify('请先移除规则和兜底目录对该分类的引用',true);return}patch({directories:props.modelValue.directories.filter(d=>d.id!==id)})}
function fallback(value){patch({fallbacks:{...props.modelValue.fallbacks,[mediaType.value]:value}})}
function addRule(){patch({rules:[...props.modelValue.rules,{id:mediaCategoryId(),name:`规则 ${props.modelValue.rules.length+1}`,mediaType:'tv',enabled:true,directoryId:props.modelValue.fallbacks.tv,when:mediaCategoryLeaf()}]})}
function rule(id,value){patch({rules:props.modelValue.rules.map(r=>r.id===id?{...r,...value}:r)})}
function ruleType(id,value){rule(id,{mediaType:value,directoryId:props.modelValue.fallbacks[value]})}
function removeRule(id){patch({rules:props.modelValue.rules.filter(r=>r.id!==id)})}
function move(index,delta){const list=[...props.modelValue.rules],to=index+delta;if(to<0||to>=list.length)return;[list[index],list[to]]=[list[to],list[index]];patch({rules:list})}
function copyRule(value,index){const list=[...props.modelValue.rules];list.splice(index+1,0,{...JSON.parse(JSON.stringify(value)),id:mediaCategoryId(),name:value.name+' 副本'});patch({rules:list})}
async function tabKey(event){if(props.disabled||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const root=event.currentTarget;tab.value=event.key==='Home'?'directories':event.key==='End'?'rules':tab.value==='rules'?'directories':'rules';await nextTick();root.querySelector('[aria-selected=true]')?.focus()}
</script>
<template>
 <section class="media-category-editor" aria-label="媒体分类配置">
  <div class="media-category-tabs" role="tablist" aria-label="媒体分类编辑栏目" @keydown="tabKey"><button type="button" role="tab" :tabindex="tab==='directories'?0:-1" :aria-selected="tab==='directories'" aria-controls="media-category-directories" :disabled="disabled" @click="tab='directories'"><Icon name="FolderTree" :size="17"/>分类目录</button><button type="button" role="tab" :tabindex="tab==='rules'?0:-1" :aria-selected="tab==='rules'" aria-controls="media-category-rules" :disabled="disabled" @click="tab='rules'"><Icon name="ListFilter" :size="17"/>分类规则</button></div>
  <section v-if="tab==='directories'" id="media-category-directories" role="tabpanel" aria-label="分类目录"><div class="media-category-types" role="group" aria-label="媒体大类"><button v-for="kind in mediaCategoryTypes" :key="kind.value" type="button" :aria-pressed="mediaType===kind.value" :disabled="disabled" @click="mediaType=kind.value"><Icon :name="kind.icon" :size="18"/>{{kind.label}}</button></div><p class="media-category-help">目录相对于{{mediaType==='tv'?'剧集':'电影'}}根目录，可用“/”分隔多层目录。</p>
   <div class="media-category-fallback field"><label>未命中规则时归入</label><RoundedSelect :model-value="modelValue.fallbacks[mediaType]" :label="`${mediaType==='tv'?'剧集':'电影'}兜底目录`" :options="fallbackOptions(mediaType)" fixed-popup :disabled="disabled" @update:model-value="fallback"/></div>
   <div class="media-category-directory-root"><Icon :name="mediaType==='tv'?'Tv':'Film'" :size="18"/><strong>{{mediaType==='tv'?'剧集':'电影'}}</strong><span>根目录</span></div>
   <article v-for="(dir,i) in directories" :key="dir.id" class="media-category-directory" :aria-label="`${mediaType==='tv'?'剧集':'电影'}分类目录 ${i+1}`"><div class="media-category-directory-fields"><label>目录名称<input :value="dir.name" :aria-label="`分类目录名称 ${i+1}`" maxlength="100" :disabled="disabled" required @input="directory(dir.id,{name:$event.target.value})"/></label><label>目录路径<input :value="dir.path.join('/')" :aria-label="`分类目录路径 ${i+1}`" maxlength="512" placeholder="例如 动画/国漫" :disabled="disabled" required @input="directory(dir.id,{path:$event.target.value.split('/')})"/></label></div><div class="media-category-directory-actions"><label><input type="checkbox" role="switch" class="switch" :aria-label="`启用分类目录 ${i+1}`" :checked="dir.enabled" :disabled="disabled||(dir.enabled&&disableUsed(dir.id))" @change="directory(dir.id,{enabled:$event.target.checked})"/>启用</label><button type="button" class="icon-btn danger-text" :aria-label="`删除分类目录 ${i+1}`" :disabled="disabled||directoryUsed(dir.id)" :data-tooltip="directoryUsed(dir.id)?'请先移除规则或兜底引用':'删除目录'" data-tooltip-always @click="removeDirectory(dir.id)"><Icon name="Trash2" :size="17"/></button></div></article>
   <button type="button" class="media-category-add" :aria-label="`添加${mediaType==='tv'?'剧集':'电影'}分类目录`" :disabled="disabled||modelValue.directories.length>=512" @click="addDirectory"><Icon name="Plus" :size="18"/>添加分类目录</button>
  </section>
  <section v-else id="media-category-rules" role="tabpanel" aria-label="分类规则"><p class="media-category-help">从上到下依次匹配，使用第一条命中的规则；未命中时使用该大类的兜底目录。</p><article v-for="(item,i) in modelValue.rules" :key="item.id" class="media-category-rule" :aria-label="`媒体分类规则 ${i+1}`"><header><strong>规则 {{i+1}}</strong><label class="media-rule-enabled"><input type="checkbox" role="switch" class="switch" :checked="item.enabled" :aria-label="`启用分类规则 ${i+1}`" :disabled="disabled" @change="rule(item.id,{enabled:$event.target.checked})"/>启用</label><div class="media-category-rule-actions"><button class="icon-btn" type="button" :aria-label="`上移分类规则 ${i+1}`" :disabled="disabled||i===0" @click="move(i,-1)"><Icon name="ArrowUp" :size="16"/></button><button class="icon-btn" type="button" :aria-label="`下移分类规则 ${i+1}`" :disabled="disabled||i===modelValue.rules.length-1" @click="move(i,1)"><Icon name="ArrowDown" :size="16"/></button><button class="icon-btn" type="button" :aria-label="`复制分类规则 ${i+1}`" :disabled="disabled||modelValue.rules.length>=512" @click="copyRule(item,i)"><Icon name="Copy" :size="16"/></button><button class="icon-btn danger-text" type="button" :aria-label="`删除分类规则 ${i+1}`" :disabled="disabled" @click="removeRule(item.id)"><Icon name="Trash2" :size="16"/></button></div></header><div class="media-category-rule-fields"><label>规则名称<input :value="item.name" :aria-label="`分类规则名称 ${i+1}`" maxlength="100" :disabled="disabled" required @input="rule(item.id,{name:$event.target.value})"/></label><div class="field"><label>媒体大类</label><RoundedSelect :model-value="item.mediaType" :label="`分类规则媒体大类 ${i+1}`" :options="mediaCategoryTypes" fixed-popup :disabled="disabled" @update:model-value="ruleType(item.id,$event)"/></div><div class="field media-category-rule-target"><label>归入目录</label><RoundedSelect :model-value="item.directoryId" :label="`分类规则归入目录 ${i+1}`" :options="ruleTargets(item)" fixed-popup :disabled="disabled" @update:model-value="rule(item.id,{directoryId:$event})"/></div></div><MediaCategoryCondition :model-value="item.when" :label="`规则${i+1}条件`" :fields="fields" :disabled="disabled" @update:model-value="rule(item.id,{when:$event})"/></article><button type="button" class="media-category-add" aria-label="添加媒体分类规则" :disabled="disabled||modelValue.rules.length>=512" @click="addRule"><Icon name="Plus" :size="18"/>添加分类规则</button></section>
 </section>
</template>
<style scoped>
.media-category-editor{grid-column:1/-1;min-width:0}.media-category-tabs{display:flex;gap:8px;border-bottom:1px solid var(--border);margin-bottom:16px;padding-bottom:10px}.media-category-tabs>button,.media-category-types>button{display:flex;align-items:center;justify-content:center;gap:7px;min-height:40px;padding:8px 14px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--muted);cursor:pointer;font-size:13px}.media-category-tabs>button[aria-selected=true],.media-category-types>button[aria-pressed=true]{color:var(--primary);background:var(--primary-soft);border-color:var(--border)}.media-category-tabs>button:hover:enabled,.media-category-types>button:hover:enabled{background:var(--primary-soft);color:var(--primary)}.media-category-types{display:flex;gap:8px}.media-category-help{font-size:12px;line-height:1.7;color:var(--muted);margin:12px 0 16px}.media-category-fallback{max-width:100%;margin-bottom:16px}.media-category-fallback>label{font-size:12px;margin-bottom:7px}.media-category-directory-root{display:flex;align-items:center;gap:8px;margin:14px 0;font-size:14px}.media-category-directory-root>svg{color:var(--primary)}.media-category-directory-root>span{font-size:12px;color:var(--muted);margin-left:auto}.media-category-directory{padding:14px;background:var(--layer-item);border:1px solid var(--border);border-radius:8px;margin:0 0 12px 12px}.media-category-directory-fields,.media-category-rule-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0}.media-category-directory label,.media-category-rule label{font-size:12px;margin:0;min-width:0}.media-category-directory input:not(.switch),.media-category-rule input:not(.switch){width:100%;height:40px;min-width:0}.media-category-directory-actions{display:flex;align-items:center;justify-content:space-between;margin-top:12px}.media-category-directory-actions>label,.media-rule-enabled{display:flex;flex-direction:row;align-items:center;gap:8px}.media-category-editor .switch{width:36px;height:20px;min-height:20px;flex:none}.media-category-add{width:100%;min-height:40px;display:flex;align-items:center;justify-content:center;gap:8px;border:1px dashed var(--border);border-radius:8px;background:transparent;color:var(--muted);cursor:pointer;font-size:13px}.media-category-add:hover:enabled{color:var(--primary);border-color:var(--primary);background:var(--primary-soft)}.media-category-add:focus-visible,.media-category-tabs>button:focus-visible,.media-category-types>button:focus-visible{outline:2px solid var(--primary);outline-offset:2px}.media-category-rule{border:1px solid var(--border);border-radius:8px;padding:14px;background:var(--layer-item);margin-bottom:14px}.media-category-rule>header{display:flex;align-items:center;gap:8px;margin-bottom:14px;min-width:0}.media-category-rule>header>strong{font-size:13px;white-space:nowrap}.media-category-rule-actions{display:flex;gap:2px;margin-left:auto;flex:none}.media-category-rule-actions>.icon-btn{width:30px;height:32px;min-height:32px}.media-category-rule-fields{margin-bottom:14px}.media-category-rule-fields>.field{min-width:0}.media-category-rule-fields>.field>label{margin-bottom:7px}.media-category-rule-target{grid-column:1/-1}.media-category-editor :deep(.rounded-select){min-width:0;max-width:100%}.media-category-editor :deep(.rounded-select-trigger){height:40px;min-width:0;max-width:100%}.media-category-editor :deep(.select-label){overflow:hidden;min-width:0}.media-category-editor :deep(.select-label+svg){flex:none}
@media(max-width:480px){.media-category-directory{margin-left:6px;padding:10px}.media-category-rule{padding:10px}.media-category-directory-fields,.media-category-rule-fields{grid-template-columns:minmax(0,1fr)}.media-category-rule>header{flex-wrap:wrap}.media-category-rule-actions{gap:0}.media-category-rule-actions>.icon-btn{width:28px}.media-category-tabs>button{padding:8px 10px}.media-rule-enabled{margin-left:auto}}
</style>
